contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entrypoint for property test
    function run(uint128 sendEther, uint256 beforeValue) public payable {
        require(address(this).balance >= sendEther);
        // read observable state before
        uint256 totalSupply_before = c.totalSupply();
        uint256 totalDistributed_before = c.totalDistributed();
        uint256 balance_before = c.balanceOf(address(this));
        bool blacklisted_before = c.blacklist(address(this));
        uint256 contractBalance_before = address(c).balance;

        // adjust the contract's public 'value' by calling nothing (we can't write it), but we can read it
        uint256 declaredValue_before = c.value();

        // attempt to call getTokens sending ETH; catch revert
        bool reverted;
        try c.getTokens{value: sendEther}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read observable state after
        uint256 totalSupply_after = c.totalSupply();
        uint256 totalDistributed_after = c.totalDistributed();
        uint256 balance_after = c.balanceOf(address(this));
        bool blacklisted_after = c.blacklist(address(this));
        uint256 contractBalance_after = address(c).balance;
        uint256 declaredValue_after = c.value();

        // General rule to assert:
        // - totalSupply never increases
        // - if getTokens succeeded (not reverted) then caller's balance increased by at most the declared value before the call,
        //   totalDistributed increased by that same amount, and caller became blacklisted (blacklist true after)
        // - if it reverted, contract state did not change (conservative: totalSupply same and balances same and totalDistributed same)
        assert(
            // totalSupply never increases
            totalSupply_after <= totalSupply_before
            && (
                // case: reverted => no changes to balances/totalDistributed/contractBalance/blacklist
                (reverted
                    && totalDistributed_after == totalDistributed_before
                    && balance_after == balance_before
                    && contractBalance_after == contractBalance_before
                    && blacklisted_after == blacklisted_before
                )
                ||
                // case: not reverted => changes consistent with minting at most declaredValue_before
                (!reverted
                    && totalDistributed_after >= totalDistributed_before
                    && totalDistributed_after - totalDistributed_before == balance_after - balance_before
                    && balance_after - balance_before <= declaredValue_before
                    && blacklisted_after == true
                )
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: attempt transferFrom and assert general invariant
    function run(address from, address to, uint256 amount) public payable {
        require(from != address(0) && to != address(0));

        // ensure this contract has enough allowance and balance to attempt a transferFrom
        // Use approve and distr/getTokens only via public functions. We can set up by having the owner (which is this contract because checker deploys c with this contract as sender) distribute tokens to `from` by calling c.distr indirectly: but distr is private.
        // However, the contract constructor set owner = msg.sender when C was deployed (msg.sender was the test deployer). The checker deploys a fresh C with owner = InvMutTest (per prompt), so InvMutTest is owner and can call functions restricted to owner.

        // Give `from` some tokens by calling c.transfer from owner (this contract) since balances[owner] initially equals totalDistributed.
        // transfer is public and will only succeed if this contract has enough balance.
        // First, read owner's balance.
        address owner = address(this);
        uint256 ownerBalBefore = c.balanceOf(owner);

        // If owner has insufficient balance to fund `from`, we skip attempting transferFrom; still must reach assert.
        // Transfer min(ownerBalBefore, amount) to `from` so `from` has tokens to transferFrom.
        uint256 fund = amount;
        if (fund > ownerBalBefore) {
            fund = ownerBalBefore;
        }
        if (fund > 0) {
            c.transfer(from, fund);
        }

        // Now approve this contract to spend `amount` from `from` by invoking approve from `from`.
        // But only msg.sender (this contract) can call approve on behalf of `from`. We cannot call approve as `from`.
        // Instead, set allowance by using transferFrom pattern: we will have `from` approve this contract only if `from` == owner (then we can call approve). So we craft the assertion to cover both cases.

        // Record balances and allowance before the transferFrom attempt
        uint256 balFromBefore = c.balanceOf(from);
        uint256 balToBefore = c.balanceOf(to);
        uint256 allowanceBefore = c.allowance(from, address(this));
        uint256 totalSupplyBefore = c.totalSupply();

        bool reverted;
        try c.transferFrom(from, to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint256 balFromAfter = c.balanceOf(from);
        uint256 balToAfter = c.balanceOf(to);
        uint256 allowanceAfter = c.allowance(from, address(this));
        uint256 totalSupplyAfter = c.totalSupply();

        // General rule asserted:
        // If the call reverted, no further condition required. If it did not revert, then:
        //  - balFromAfter = balFromBefore - amount
        //  - balToAfter = balToBefore + amount
        //  - allowanceAfter = allowanceBefore - amount (but allowance cannot underflow)
        //  - totalSupplyAfter == totalSupplyBefore (transferFrom doesn't change totalSupply)
        // We express this as one combined assert using implication pattern.
        assert(reverted ||
               (balFromBefore >= amount &&
                allowanceBefore >= amount &&
                balFromAfter + amount == balFromBefore &&
                balToAfter == balToBefore + amount &&
                allowanceAfter + amount == allowanceBefore &&
                totalSupplyAfter == totalSupplyBefore)
        );
    }

    // fallback to accept ether if needed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: perform transfer and assert invariant
    function run(address from, address to, uint256 amount) public payable {
        require(from != address(0) && to != address(0));

        // Read pre-call observable state
        uint256 balFromBefore = c.balanceOf(from);
        uint256 balToBefore = c.balanceOf(to);
        uint256 totalSupplyBefore = c.totalSupply();

        bool reverted;
        // Attempt to call transfer as the test contract (msg.sender will be this contract)
        // Use try/catch to observe revert without aborting the test
        try c.transfer(to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-call observable state
        uint256 balFromAfter = c.balanceOf(from);
        uint256 balToAfter = c.balanceOf(to);
        uint256 totalSupplyAfter = c.totalSupply();

        // General rule:
        // If transfer reverted then balances and totalSupply did not change.
        // If transfer succeeded then it must have taken tokens from sender (if they had enough)
        // and credited receiver by the same amount, and totalSupply remains equal.
        // We express both cases in one assert.
        assert(
            // reverted implies no observable change
            (reverted && balFromAfter == balFromBefore && balToAfter == balToBefore && totalSupplyAfter == totalSupplyBefore)
            ||
            // not reverted implies the canonical transfer semantics
            (!reverted && balFromBefore >= amount && balFromAfter + amount == balFromBefore && balToAfter == balToBefore + amount && totalSupplyAfter == totalSupplyBefore)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address spender, uint256 value) public payable {
        // require sensible non-zero addresses to avoid trivial failures
        require(spender != address(0));

        // observe allowance before
        uint256 before = c.allowance(address(this), spender);

        bool reverted;
        try c.approve(spender, value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = c.allowance(address(this), spender);

        // If approve reverted, allowance must be unchanged; otherwise it must equal the requested value.
        assert((reverted && after == before) || (!reverted && after == value));
    }

    receive() external payable {}
}

