contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call c.transfer(from=this contract (InvMutTest deployed as owner initially), to, amt)
    // The test function takes a recipient and an amount. It first ensures this contract has enough balance
    // by relying on the initial distribution to the deployer of C: the checker deploys a fresh C and
    // passes it into this test's constructor, so owner is this test contract. The constructor of C
    // (NETM) sets balances[owner] = totalDistributed. We require amt <= that balance.
    function run(address to, uint256 amt) public payable {
        require(to != address(0));
        // observe totalSupply and balances before
        uint256 supplyBefore = c.totalSupply();
        uint256 balSenderBefore = c.balanceOf(address(this));
        uint256 balToBefore = c.balanceOf(to);

        // precondition: we can only test transfer when sender has at least amt
        require(balSenderBefore >= amt);

        // Call transfer; capture whether it reverted
        bool reverted;
        try c.transfer(to, amt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-values
        uint256 supplyAfter = c.totalSupply();
        uint256 balSenderAfter = c.balanceOf(address(this));
        uint256 balToAfter = c.balanceOf(to);

        // General rule:
        // If transfer did not revert then totalSupply is unchanged and
        // sender balance decreased by amt and recipient balance increased by amt.
        // If it reverted then balances and supply did not change.
        assert(
            (!reverted && supplyAfter == supplyBefore && balSenderBefore - balSenderAfter == amt && balToAfter - balToBefore == amt)
            || (reverted && supplyAfter == supplyBefore && balSenderAfter == balSenderBefore && balToAfter == balToBefore)
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test transferFrom when this contract has an allowance from `from` and `from` has sufficient balance.
    // Parameters: from (address granting allowance), to (recipient), amt (amount to transfer), allowanceAmt (amount approved to this contract)
    function run(address from, address to, uint256 amt, uint256 allowanceAmt) public payable {
        require(from != address(0) && to != address(0));
        // Observe pre-state
        uint256 supplyBefore = c.totalSupply();
        uint256 balFromBefore = c.balanceOf(from);
        uint256 balToBefore = c.balanceOf(to);
        uint256 allowBefore = c.allowance(from, address(this));

        // Preconditions: from must have at least amt, and we will only call transferFrom when allowanceAmt >= amt
        // We require that this test contract currently has allowance <= allowanceAmt so that an approve we will perform can succeed.
        require(balFromBefore >= amt);
        require(allowanceAmt >= amt);

        // First, have `from` approve this contract for allowanceAmt by calling approve from `from`.
        // Since calls originate from this contract, we need `from` to be this contract to perform approve on its behalf.
        // The deployed C sets its owner to msg.sender at deployment (the test deployer). The checker deploys c and passes it to us,
        // so we cannot make arbitrary other addresses call approve. Therefore only proceed if `from == address(this)`.
        require(from == address(this));

        // Approve allowanceAmt for this contract (self-approve). This will set allowance(from,this) = allowanceAmt.
        bool okApprove;
        try c.approve(address(this), allowanceAmt) returns (bool r) { okApprove = r; } catch { okApprove = false; }

        // Now attempt transferFrom(from, to, amt) and record whether it reverted.
        bool reverted;
        try c.transferFrom(from, to, amt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-state
        uint256 supplyAfter = c.totalSupply();
        uint256 balFromAfter = c.balanceOf(from);
        uint256 balToAfter = c.balanceOf(to);
        uint256 allowAfter = c.allowance(from, address(this));

        // Assertion: exactly one of two cases holds:
        // - If transferFrom succeeded (did not revert) then totalSupply unchanged, from decreased by amt, to increased by amt, and allowance decreased by amt (unless approve failed earlier)
        // - If transferFrom reverted then nothing changed (balances and supply and allowance unchanged)
        assert((!reverted && supplyAfter == supplyBefore && balFromBefore - balFromAfter == amt && balToAfter - balToBefore == amt && (okApprove ? (allowBefore == allowanceAmt && allowAfter + amt == allowanceAmt) : true))
               || (reverted && supplyAfter == supplyBefore && balFromAfter == balFromBefore && balToAfter == balToBefore && allowAfter == allowBefore));
    }

    receive() external payable { }
}
